/*
 * DS3231 RTC Clock + LCD + Hourly NTP Sync (non-blocking)
 *
 * Uses ntpEpoch() to fetch real UTC time from the browser.
 * Syncs the DS3231 RTC every hour using millis() timers.
 * Displays time and temperature on Serial + 16x2 I2C LCD.
 *
 * Wiring:
 *   DS3231 & LCD share I2C bus: SDA->D21, SCL->D22
 *   Both powered from 3V3
 */

#include <Wire.h>
#include <RtcDS3231.h>
#include <LiquidCrystal_I2C.h>
#include <WiFi.h>

// IST = UTC + 5:30 = 19800 seconds
// Change this for your timezone
var gmtOffsetSec = 19800;

// Non-blocking intervals
var DISPLAY_INTERVAL = 1000;
var NTP_SYNC_INTERVAL = 3600000;

var lastDisplayTime = 0;
var lastNtpSyncTime = 0;

RtcDS3231<TwoWire> Rtc(Wire);
LiquidCrystal_I2C lcd(0x27, 16, 2);

// Helper: sync RTC from NTP
// NOTE: Do NOT use Math.floor() — the transpiler double-prefixes it.
// Use floor() instead (transpiler auto-adds Math. prefix).
void syncRtcFromNtp() {
  var epoch = ntpEpoch() + gmtOffsetSec;
  var h = floor((epoch % 86400) / 3600);
  var m = floor((epoch % 3600) / 60);
  var s = floor(epoch % 60);
  Rtc.SetDateTime(RtcDateTime(2026, 1, 1, h, m, s));
  Serial.print("[NTP] Synced: ");
  if (h < 10) Serial.print("0");
  Serial.print(h);
  Serial.print(":");
  if (m < 10) Serial.print("0");
  Serial.print(m);
  Serial.print(":");
  if (s < 10) Serial.print("0");
  Serial.println(s);
}

void setup() {
  Serial.begin(115200);
  Wire.begin();
  lcd.init();
  lcd.backlight();

  // Connect WiFi (simulated)
  WiFi.begin("ArduSimNet", "simulator");
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
  }
  Serial.println("WiFi connected");

  // Initialize RTC
  Rtc.Begin();
  if (!Rtc.IsDateTimeValid()) {
    Serial.println("RTC lost power - setting from NTP");
  }
  if (!Rtc.IsRunning()) {
    Rtc.SetIsRunning(true);
  }

  // Sync immediately on boot
  syncRtcFromNtp();

  lastNtpSyncTime = millis();
  lastDisplayTime = millis();

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("DS3231 + NTP");
  lcd.setCursor(0, 1);
  lcd.print("Syncing...");
  delay(1500);
  lcd.clear();
}

void loop() {
  var now = millis();

  // Non-blocking NTP sync every 1 hour
  if (now - lastNtpSyncTime >= NTP_SYNC_INTERVAL || lastNtpSyncTime == 0) {
    lastNtpSyncTime = now;
    syncRtcFromNtp();
  }

  // Non-blocking 1-second display refresh
  if (now - lastDisplayTime >= DISPLAY_INTERVAL) {
    lastDisplayTime = now;
    RtcDateTime dt = Rtc.GetDateTime();
    RtcTemperature temp = Rtc.GetTemperature();

    // Serial output
    if (dt.Hour() < 10) Serial.print("0");
    Serial.print(dt.Hour());
    Serial.print(":");
    if (dt.Minute() < 10) Serial.print("0");
    Serial.print(dt.Minute());
    Serial.print(":");
    if (dt.Second() < 10) Serial.print("0");
    Serial.print(dt.Second());
    Serial.print("  ");
    if (dt.Day() < 10) Serial.print("0");
    Serial.print(dt.Day());
    Serial.print("/");
    if (dt.Month() < 10) Serial.print("0");
    Serial.print(dt.Month());
    Serial.print("/");
    Serial.print(dt.Year());
    Serial.print("  Temp: ");
    Serial.print(temp.AsFloatDegC(), 1);
    Serial.println(" C");

    // LCD row 0: time
    lcd.setCursor(0, 0);
    if (dt.Hour() < 10) lcd.print("0");
    lcd.print(dt.Hour());
    lcd.print(":");
    if (dt.Minute() < 10) lcd.print("0");
    lcd.print(dt.Minute());
    lcd.print(":");
    if (dt.Second() < 10) lcd.print("0");
    lcd.print(dt.Second());
    lcd.print("  ");
    lcd.print(temp.AsFloatDegC(), 1);
    lcd.print("C");

    // LCD row 1: date
    lcd.setCursor(0, 1);
    if (dt.Day() < 10) lcd.print("0");
    lcd.print(dt.Day());
    lcd.print("/");
    if (dt.Month() < 10) lcd.print("0");
    lcd.print(dt.Month());
    lcd.print("/");
    lcd.print(dt.Year());
  }
}
